beforeExample:
import java.util.ArrayList;
import java.util.List;

public class Example {
    public void foo() {
        List<String> list = new ArrayList<>();
        try {
            list.get(10); // Throws IndexOutOfBoundsException, specifically ArrayIndexOutOfBoundsException
        } catch (ArrayIndexOutOfBoundsException x) {
            System.err.println("Caught AIOOBE: " + x.getMessage());
        }
    }
}

afterExample:
import java.util.ArrayList;
import java.util.IndexOutOfBoundsException;
import java.util.List;

public class Example {
    public void foo() {
        List<String> list = new ArrayList<>();
        try {
            list.get(10);
        } catch (IndexOutOfBoundsException x) { // Changed to IndexOutOfBoundsException
            System.err.println("Caught IOOBE: " + x.getMessage());
        }
    }
}

negativeExample:
import java.io.IOException;

public class Example {
    public void foo() {
        try {
            // some I/O operation
        } catch (IOException e) { // Should not match other exception types
            System.err.println(e.getMessage());
        }
    }
}
